-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION accept_r5b_effect_memo_witness(p_ref_id text, p_canonical_claim_hash text, p_observers text[])
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM quorum_acceptance WHERE claim_id = p_ref_id AND procedure = 'r5b_effect_memo_witness') THEN
        RAISE EXCEPTION 'already accepted';
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(p_observers) o(id) WHERE NOT EXISTS (SELECT 1 FROM authorized_observer a WHERE a.observer_set = 'witness_oracles' AND a.observer_id = o.id)) THEN
        RAISE EXCEPTION 'unauthorized observer';
    END IF;
    IF (SELECT count(*) FROM unnest(p_observers)) <> (SELECT count(DISTINCT o.id) FROM unnest(p_observers) o(id)) THEN
        RAISE EXCEPTION 'duplicate observer';
    END IF;
    IF (SELECT count(DISTINCT o.id) FROM unnest(p_observers) o(id)) < 2 THEN
        RAISE EXCEPTION 'quorum not met';
    END IF;
    INSERT INTO quorum_acceptance(procedure, claim_id, canonical_claim_hash, observer_count)
    VALUES ('r5b_effect_memo_witness', p_ref_id, p_canonical_claim_hash, (SELECT count(DISTINCT o.id) FROM unnest(p_observers) o(id)));
END;
$$;

CREATE OR REPLACE FUNCTION execute_r5b_effect_memo_witness(p_ref_id text, p_payer_id text, p_custodian_id text, p_payee_id text, p_amount bigint, p_threshold bigint, p_currency text, p_clearance_proof text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_ref_id AND procedure = 'r5b_effect_memo_witness' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM quorum_acceptance WHERE claim_id = p_ref_id AND procedure = 'r5b_effect_memo_witness') THEN
        RAISE EXCEPTION 'quorum not accepted';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_ref_id, 'r5b_effect_memo_witness')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit reserve_debit (payer.reserve)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for reserve_debit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('payer.reserve', p_payer_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key, memo)
    VALUES ('r5b_effect_memo_witness', 'reserve_debit', 'payer.reserve', p_payer_id, p_amount, p_currency, -(p_amount), p_ref_id, 'r5b-memo');

    -- credit custody_credit (custody.holding)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for custody_credit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('custody.holding', p_custodian_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key, memo)
    VALUES ('r5b_effect_memo_witness', 'custody_credit', 'custody.holding', p_custodian_id, p_amount, p_currency, p_amount, p_ref_id, 'r5b-memo');

    -- debit release_debit (custody.holding)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for release_debit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('custody.holding', p_custodian_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('r5b_effect_memo_witness', 'release_debit', 'custody.holding', p_custodian_id, p_amount, p_currency, -(p_amount), p_ref_id);

    -- credit settle_credit (payee.proceeds)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for settle_credit';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('payee.proceeds', p_payee_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('r5b_effect_memo_witness', 'settle_credit', 'payee.proceeds', p_payee_id, p_amount, p_currency, p_amount, p_ref_id);

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'r5b_effect_memo_witness' AND idempotency_key = p_ref_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_ref_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('r5b_effect_memo_witness', p_ref_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;

-- Admission control (): accept_ is the quorum guard. Postgres grants EXECUTE to PUBLIC
-- by default and the observer ids are not secret, so a PUBLIC-callable accept_ is forgeable.
-- REVOKE it (no-access-by-default / fail-safe); the deployer MUST then GRANT it to ONLY the
-- off-chain aggregator role, e.g.:  GRANT EXECUTE ON FUNCTION accept_r5b_effect_memo_witness(text, text, text[]) TO <aggregator_role>;
REVOKE EXECUTE ON FUNCTION accept_r5b_effect_memo_witness(text, text, text[]) FROM PUBLIC;
